async function api(path:string,method='GET',data?:unknown){
 const r=await fetch('/api'+path,{method,headers:{'Content-Type':'application/json','X-VoxStage':'1'},body:data===undefined?undefined:JSON.stringify(data)});
 const value=await r.json(); if(!r.ok){const err=new Error(typeof value.detail==='string'?value.detail:(value.detail&&typeof value.detail.message==='string')?value.detail.message:'请求未完成，请检查输入并重试') as Error&{status?:number;detail?:unknown};err.status=r.status;err.detail=value.detail;throw err}return value;
}
// A colour per character on screen: the author's choice when made, else a
// palette split by the voice's sex as its label describes it — cool colours for
// male voices, warm for female — the narrator in near-black. Screen only.
// The author's palette (2026-09-14). The split by sex only drives the automatic
// choice; the picker offers every swatch to every character.
const MALE_COLORS=['#000080','#008000','#00b0f0','#4a442a','#548dd4','#027f02','#333399','#00b050','#339966'];
const FEMALE_COLORS=['#800080','#8064a2','#e36c0a','#ff0000','#7030a0'];
const PLAIN_COLORS=['#000000','#26302f','#4a4a4a','#8a8f81','#bfbfbf'];   // black, the interface's text colour, greys — for narrators; the light one for a dark theme later
const OTHER_COLORS=['#4a442a','#8064a2','#339966','#548dd4'];
function voiceSex(label:string){const l=label.toLowerCase();if(/女|female|girl|woman/.test(l))return 'f';if(/男|male|boy|man\b/.test(l))return 'm';return '?'}
function speakerColors(p:Project,voiceLabels:Record<string,string>,custom:{id:string;name:string;derived_from?:string|null}[]){
 const out:Record<string,string>={};const used={m:0,f:0,'?':0};
 // A character's automatic colour is fixed by their place among the
 // characters of the same sex, explicit ones included: choosing a colour for
 // one must not shift everyone after them (本人 2026-09-16).
 for(const [speaker,voice] of Object.entries(p.voices)){
  const explicit=p.colors?.[speaker];
  if(/^(旁白|narrator)$/i.test(speaker)){out[speaker]=explicit??'#26302f';continue}
  const origin=voice.startsWith('custom:')?(custom.find(v=>'custom:'+v.id===voice)?.derived_from??''):voice;
  const label=(voiceLabels[origin.split(' · ')[0]]??'')+' '+origin;         // a take kept from Ryan is as male as Ryan
  // The sex the author set for the character comes first; the voice's own
  // description is only the default (本人 2026-09-17: the setting had no
  // visible effect).
  const stated=p.sexes?.[speaker];
  const sex=stated==='m'||stated==='f'?stated:voiceSex(label+' '+(voice.startsWith('custom:')?'':voice));
  const palette=sex==='m'?MALE_COLORS:sex==='f'?FEMALE_COLORS:OTHER_COLORS;
  out[speaker]=explicit??palette[used[sex]%palette.length];used[sex]++;
 }
 return out;
}
